        "User": {
          "userId": "eid_932ce89c",
          "timestamp": "2026-06-23T23:58:00",
          "text": "Will do! Thanks for the quick review, team. I'll ping you once the updates are ready. Have a great day! ☀️",
          "utterranceID": "20260625-8-bfbe9"
        },
        "Reactions": []
      },
